            if g[i][j]==1 and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=set()
                while stack:
                    a,b=stack.pop(); cells.add((a,b))
                    for di,dj in off4:
                        x,y=a+di,b+dj
                        if 0<=x<H and 0<=W and g[x][y]==1 and not seen[x][y]:
                            seen[x][y]=True; stack.append((x,y))
                cc.append(cells)
    # corrected offsets
