        stack=[(i,j)]; seen[i][j]=True; res=set()
        while stack:
            a,b=stack.pop(); res.add((a,b))
            for di,dj in off4:
                x,y=a+di,b+dj
                if 0<=x<H and 0<=y<W and g[x][y]==1 and not seen[x][y]:
                    seen[x][y]=True; stack.append((x,y))
        return res
    cc=[]
