        for i in range(r0-1,r1+2):
            for j in range(c0-1,c1+2):
                if g[i][j]==0 and not (r0-1<=i<=r1 and c0-1<=j<=c1):
                    if not vis[i][j]: vis[i][j]=True; q.append((i,j))
        for i,j in list(range(H)) + []: pass
        # redo: start flood from any zero outside bbox
        vis=[[False]*W for _ in range(H)]
        st=[(i,j) for i in range(H) for j in range(W) if g[i][j]==0 and not (r0<=i<=r1 and c0<=j<=c1)]
        for x,y in st: vis[x][y]=True; q.append((x,y))
        offs8=off4+[(1,1),(1,-1),(-1,1),(-1,-1)]
        while q:
            a,b=q.pop()
            for di,dj in offs8:
                x,y=a+di,b+dj
                if 0<=x<H and 0<=y<W and g[x][y]==0 and not vis[x][y]:
                    vis[x][y]=True; q.append((x,y))
        enc={(i,j) for i in range(r0,r1+1) for j in range(c0,c1) if g[i][j]==0 and not vis[i][j]}
        adj={p for p in s2}
        for p in s2:
