    pred=[[0]*W for _ in range(H)]
    # 2: zero cells adjacent (8-dir) to any non-zero cell
    # 3: enclosed zeros
    # 0: everything else
    shape=[(i,j) for i in range(H) for j in range(W) if g[i][j]!=0]
    D4=[(1,0),(-1,0),(0,1),(0,-1)]; D8=D4+[(1,1),(1,-1),(-1,1),(-1,-1)]
    R=set(); q=deque()
    for i in (0,H-1):
        for j in range(W):
            if g[i][j]==0 and (i,j) not in R: q.append((i,j)); R.add((i,j))
    for j in (0,W-1):
        for i in range(H):
            if g[i][j]==0 and (i,j) not in R: q.append((i,j)); R.add((i,j))
    while q:
        x,y=q.popleft()
        for dx,dy in D4:
            nx,ny=x+dx,y+dy
            if 0<=nx<H and 0<=ny<W and g[nx][ny]==0 and (nx,ny) not in R:
                R.add((nx,ny)); q.append((nx,ny))
    for i in range(H):
        for j in range(W):
            if g[i][j]==0:
                adj=any(abs(i-x)<=1 and abs(j-y)<=1 for x,y in shape)
                enc=(i,j) not in R
                pred[i][j]=2 if adj else (3 if enc else 0)
    return pred
